//go:build e2e

package e2e

import (
	"os"
	"path"
	"regexp"
	"testing"

	"github.com/sirupsen/logrus"
	"github.com/stretchr/testify/assert"
)

var ansiRegex = regexp.MustCompile(`\x1b\[[0-9;]*m`)

var (
	slog = logrus.WithField("component", "script_test")
)

// Help text is now generated by Cobra from each command's registered flags/Long/Example fields
// (internal/plugin), not scripts/help.sh's hand-written, ANSI-highlighted prose, so these
// assertions check the commands/flags are actually present rather than matching exact formatting.
func TestHelpCommand(t *testing.T) {
	t.Run("help command", func(t *testing.T) {
		output, err := RunCommand(slog, "commands/oc-netobserv", "help")
		assert.Nil(t, err)

		err = os.WriteFile(path.Join("output", StartupDate+"-helpOutput"), []byte(output), 0666)
		assert.Nil(t, err)

		assert.NotEmpty(t, output)
		assert.Contains(t, output, "deploys the NetObserv eBPF agent")
		assert.Contains(t, output, "SrcK8S_Namespace")
		assert.Contains(t, output, "flows --drops")
		assert.Contains(t, output, "Available Commands:")
		for _, cmd := range []string{"flows", "packets", "metrics", "follow", "stop", "copy", "cleanup", "version"} {
			assert.Contains(t, output, cmd)
		}
		assert.NotContains(t, output, "completion")
	})

	t.Run("no argument shows help", func(t *testing.T) {
		output, err := RunCommand(slog, "commands/oc-netobserv")
		assert.Nil(t, err)
		assert.NotEmpty(t, output)
		assert.Contains(t, output, "Available Commands:")
	})
}

func TestSubcommandHelp(t *testing.T) {
	t.Run("flows help as positional command", func(t *testing.T) {
		output, err := RunCommand(slog, "commands/oc-netobserv", "flows", "help")
		assert.Nil(t, err)
		plain := ansiRegex.ReplaceAllString(output, "")
		assert.Contains(t, plain, "netobserv flows")
		assert.Contains(t, plain, "Flags:")
		assert.Contains(t, plain, "--sampling")
	})

	t.Run("flows --help", func(t *testing.T) {
		output, err := RunCommand(slog, "commands/oc-netobserv", "flows", "--help")
		assert.Nil(t, err)
		assert.NotEmpty(t, output)
		plain := ansiRegex.ReplaceAllString(output, "")
		assert.Contains(t, plain, "netobserv flows")
		assert.Contains(t, plain, "Flags:")
		assert.Contains(t, plain, "--sampling")
		assert.Contains(t, plain, "--enable_all")
		assert.Contains(t, plain, "Examples:")
	})

	t.Run("flows --help at any position", func(t *testing.T) {
		output, err := RunCommand(slog, "commands/oc-netobserv", "flows", "--port=8080", "--help")
		assert.Nil(t, err)
		assert.NotEmpty(t, output)
		plain := ansiRegex.ReplaceAllString(output, "")
		assert.Contains(t, plain, "netobserv flows")
		assert.Contains(t, plain, "Flags:")
	})

	t.Run("packets --help", func(t *testing.T) {
		output, err := RunCommand(slog, "commands/oc-netobserv", "packets", "--help")
		assert.Nil(t, err)
		assert.NotEmpty(t, output)
		plain := ansiRegex.ReplaceAllString(output, "")
		assert.Contains(t, plain, "netobserv packets")
		assert.Contains(t, plain, "--enable_openssl")
	})

	t.Run("metrics --help", func(t *testing.T) {
		output, err := RunCommand(slog, "commands/oc-netobserv", "metrics", "--help")
		assert.Nil(t, err)
		assert.NotEmpty(t, output)
		plain := ansiRegex.ReplaceAllString(output, "")
		assert.Contains(t, plain, "netobserv metrics")
		assert.Contains(t, plain, "--include_list")
	})
}

func TestVersionCommand(t *testing.T) {
	t.Run("version command", func(t *testing.T) {
		output, err := RunCommand(slog, "commands/oc-netobserv", "version")
		assert.Nil(t, err)

		err = os.WriteFile(path.Join("output", StartupDate+"-versionOutput"), []byte(output), 0666)
		assert.Nil(t, err)

		assert.NotEmpty(t, output)
		assert.Contains(t, output, "NetObserv CLI version test")
	})
}
